    private String nativeStatus(){String label=(dubbing==null||dubbing.isEmpty())?(playback==null?"":ApiRepository.downloadSourceName(playback.provider)):dubbing+(yummyVersion==null||yummyVersion.isEmpty()?"":" · "+yummyVersion);return "Серия "+number(wantedEpisode)+(label.isEmpty()?"":" · "+label);}
    private int resumeFor(double ep){JSONObject h=YoruApp.app().store.progress(anime);return Double.compare(h.optDouble("episode",-1),ep)==0?h.optInt("time")*1000:0;}
    private void loadMode(String selected){mode=selected==null||selected.isEmpty()?"auto":selected;save(true);seekMs=resumeFor(wantedEpisode);stopMedia();nativeMode=false;dubbing="";yummyVersion="";int gen=++generation;loading.setVisibility(View.VISIBLE);status.setText(mode.equals("yoru")?"YORU Source ищет рабочие варианты…":"Подключаем каталог…");setup=true;selectors.setVisibility(View.GONE);epRow.setVisibility(View.GONE);skip.setVisibility(View.GONE);int sourceIndex=Math.max(0,Arrays.asList(ApiRepository.PLAYER_IDS).indexOf(mode));if(sourceSelect!=null&&sourceSelect.getSelectedItemPosition()!=sourceIndex)sourceSelect.setSelection(sourceIndex);setup=false;YoruApp.app().io.execute(()->{try{Anime.Playback ready=YoruApp.app().api.playback(anime,mode);YoruApp.app().main.post(()->{if(gen!=generation||isFinishing())return;playback=ready;anime=ready.catalog;title.setText(YoruBrain.title(anime));if(ready.video!=null&&!ready.video.episodeList.isEmpty()){setup=true;selectors.setVisibility(View.VISIBLE);epRow.setVisibility(View.VISIBLE);ArrayList<String> labels=new ArrayList<>();int index=0;for(int i=0;i<ready.video.episodeList.size();i++){Anime.Episode e=ready.video.episodeList.get(i);labels.add(YoruApp.app().store.spoilerSafe()?"Серия "+number(e.number):e.label());if(Double.compare(e.number,wantedEpisode)==0)index=i;}episodeSelect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));episodeSelect.setSelection(index);setup=false;loadEpisode(ready.video.episodeList.get(index));}else{episode=null;selectors.setVisibility(View.GONE);epRow.setVisibility(View.GONE);String url=ready.directUrl;if(ready.directKodik&&!Uri.parse(url).getPath().startsWith("/video/"))url=Uri.parse(url).buildUpon().appendQueryParameter("episode",number(wantedEpisode)).build().toString();showWeb(url,ready.directKodik);}});}catch(Exception e){YoruApp.app().main.post(()->{if(gen==generation&&!isFinishing())error("Каталог сейчас не вернул видео. Нажмите «Обновить» или выберите другой каталог.");});}});}
    private void loadEpisode(Anime.Episode e){save(true);resetFrameDownloads();stopMedia();episode=e;wantedEpisode=e.number;browserTime=0;browserDuration=0;playing=false;openingSkipped=false;rescueTries=0;currentVariantKey="";int gen=++generation;loading.setVisibility(View.VISIBLE);status.setText(e.lazy.equals("yoru")?"YORU Source проверяет серию "+number(e.number)+"…":"Загружаем серию "+number(e.number)+"…");YoruApp.app().io.execute(()->{try{YoruApp.app().api.loadEpisode(e);YoruApp.app().main.post(()->{if(gen!=generation||episode!=e||isFinishing())return;setup=true;qualityRow.setVisibility(e.streams.isEmpty()?View.GONE:View.VISIBLE);voiceSelect.setVisibility(e.variants.isEmpty()?View.GONE:View.VISIBLE);int labelIndex=selectors.indexOfChild(voiceSelect)-1;if(labelIndex>=0)selectors.getChildAt(labelIndex).setVisibility(e.variants.isEmpty()?View.GONE:View.VISIBLE);if(!e.streams.isEmpty()){dubbing="";yummyVersion="";ArrayList<Integer> qs=new ArrayList<>(e.streams.keySet());if(!e.streams.containsKey(quality)){quality=qs.get(0);for(int q:qs)if(q<=(YoruApp.app().savingMobile()?480:YoruApp.app().store.quality()))quality=q;}ArrayList<String> names=new ArrayList<>();for(int q:qs)names.add(q>0?q+"p":"Оригинал");qualitySelect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));qualitySelect.setSelection(qs.indexOf(quality));setup=false;playNative(e.streams.get(quality));}else if(!e.variants.isEmpty()){ArrayList<String> names=new ArrayList<>();int selected=0,firstVoice=-1,exact=-1;String preferred=dubbing==null||dubbing.isEmpty()?YoruApp.app().store.voicePreference():dubbing;String pref=preferred==null?"":preferred.toLowerCase(Locale.ROOT);for(int i=0;i<e.variants.size();i++){Anime.Variant choice=e.variants.get(i);names.add(ApiRepository.cleanLabel(choice.label()));String cn=ApiRepository.cleanLabel(choice.name).toLowerCase(Locale.ROOT);if(choice.name.equals(dubbing)){if(firstVoice<0)firstVoice=i;if(exact<0&&choice.player.equals(yummyVersion))exact=i;}else if(firstVoice<0&&!pref.isEmpty()&&(cn.contains(pref)||pref.contains(cn)))firstVoice=i;}if(exact>=0)selected=exact;else if(firstVoice>=0)selected=firstVoice;voiceSelect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));voiceSelect.setSelection(selected);setup=false;showVariant(e.variants.get(selected));}else{setup=false;error("Для этой серии пока нет доступного видео.");}updateNext();});}catch(Exception err){YoruApp.app().main.post(()->{if(gen==generation&&!isFinishing())error("Серия сейчас недоступна. Попробуйте другой каталог.");});}});}
    private void showVariant(Anime.Variant v){dubbing=ApiRepository.cleanLabel(v.name);yummyVersion=ApiRepository.cleanLabel(v.player);if(episode!=null){episode.streams.clear();episode.openingStart=v.openingStart;episode.openingEnd=v.openingEnd;}String safe=ApiRepository.embed(v.url);if(safe.isEmpty())safe=ApiRepository.safeUrl(v.url);if(safe.isEmpty()){error(activeSourceLabel()+" не открыл эту серию.");return;}int gen=++generation;currentUrl=safe;nativeMode=false;yummyFrame=false;trustedKodik=false;video.setVisibility(View.VISIBLE);web.setVisibility(View.GONE);loading.setVisibility(View.VISIBLE);status.setText("Подключаем встроенный просмотр…");currentVariantKey=safe;String expected=safe;boolean kodik=Uri.parse(expected).getHost()!=null&&Uri.parse(expected).getHost().endsWith("kodikplayer.com");YoruApp.app().io.execute(()->{try{TreeMap<Integer,String> streams=YoruApp.app().api.resolveStreams(v.url);YoruApp.app().main.post(()->{if(gen!=generation||destroyed||isFinishing()||!expected.equals(currentUrl))return;if(streams!=null&&!streams.isEmpty())playVariantNative(streams);else showWeb(expected,kodik);});}catch(Exception ignored){YoruApp.app().main.post(()->{if(gen==generation&&!destroyed&&!isFinishing()&&expected.equals(currentUrl))showWeb(expected,kodik);});}});}
